<script setup lang="ts">
import { computed } from 'vue'
import { MAlert, MBadge, MButton, MCard, MEmptyState, MIcon } from '@getcortexlabs/mavis-web'
import { formatCount as n, type LearningData, type Overview } from '../lib/api'
const props = defineProps<{ learning: LearningData; overview: Overview; evaluation?: boolean }>()
defineEmits<{ navigate: [key: string] }>()
const stats = computed(() => props.learning.stats)
const active = computed(() => props.learning.lessons.filter(l => l.state === 'active' && !l.has_conflict).length)
const omitted = computed(() => Object.entries(stats.value.selection).filter(([key]) => key !== 'delivered').reduce((sum, [, value]) => sum + value, 0))
const reasons: Record<string, string> = { 'already-in-prompt': 'Já estava no pedido', conflict: 'Aguardando revisão', 'low-usefulness': 'Pouco útil para a tarefa' }
const totalUsage = computed(() => { const u = stats.value.usage; return u.input_tokens + u.output_tokens + u.cache_creation_tokens + u.cache_read_tokens })
</script>

<template>
  <div class="stack">
    <MCard v-if="!evaluation" class="welcome-card" padding="xl">
      <div class="welcome-copy"><p class="eyebrow">CONTINUIDADE, SEM REPETIÇÃO</p><h2>Menos contexto.<br>Mais do que importa.</h2><p>Aprendizados úteis acompanham suas tarefas. Repetições ficam de fora, e o que mudou volta para revisão.</p><MButton icon="arrow-right" @click="$emit('navigate', 'learning')">Explorar aprendizados</MButton></div>
      <div class="memory-orbit" aria-hidden="true"><div class="orbit-ring ring-one"></div><div class="orbit-ring ring-two"></div><span class="orbit-core"><MIcon name="brain" :size="42" /></span><span class="orbit-label orbit-a"><MIcon name="check-check" :size="16" />Aprender</span><span class="orbit-label orbit-b"><MIcon name="git-branch" :size="16" />Relacionar</span><span class="orbit-label orbit-c"><MIcon name="list-todo" :size="16" />Continuar</span></div>
    </MCard>
    <div class="metric-grid">
      <MCard><span class="metric-label">{{ evaluation ? 'Tokens medidos' : 'Aprendizados prontos' }}</span><strong class="metric-value">{{ n(evaluation ? totalUsage : active) }}</strong><small>{{ evaluation ? 'Entrada, saída e cache do provedor' : 'Ativos e sem conflitos em aberto' }}</small></MCard>
      <MCard><span class="metric-label">Repetições evitadas</span><strong class="metric-value">{{ n(stats.repeat_tokens_avoided + stats.reads.avoided_tokens) }}</strong><small>Tokens estimados · memória e arquivos</small></MCard>
      <MCard><span class="metric-label">{{ evaluation ? 'Contextos omitidos' : 'Tarefas em andamento' }}</span><strong class="metric-value">{{ n(evaluation ? omitted : stats.tasks_open) }}</strong><small>{{ evaluation ? 'Informação repetida ou pouco útil' : 'Pontos de retomada salvos' }}</small></MCard>
      <MCard><span class="metric-label">Pedem sua revisão</span><strong class="metric-value">{{ n(stats.conflicts_open) }}</strong><small>Regras divergentes ficam suspensas</small></MCard>
    </div>
    <div v-if="!evaluation" class="two-columns">
      <MCard gap="lg"><div class="section-heading"><h2>O que acontece agora</h2><MBadge text="Automático" tone="success" /></div><div class="explain-row"><span class="step">01</span><div><h3>Observa antes de generalizar</h3><p>Preferências ficam compartilhadas após {{ stats.confirmations_required }} confirmações. Pedidos explícitos podem valer imediatamente.</p></div></div><div class="explain-row"><span class="step">02</span><div><h3>Lembra quando faz sentido</h3><p>Usa o assunto, as condições, a validade dos arquivos e o seu feedback para selecionar o contexto.</p></div></div><div class="explain-row"><span class="step">03</span><div><h3>Respeita o espaço da conversa</h3><p>Até {{ stats.max_context_tokens }} tokens por pedido e {{ stats.max_session_tokens }} por sessão para memória e detalhes.</p></div></div></MCard>
      <MCard gap="lg"><h2>Seu próximo passo</h2><MAlert v-if="stats.conflicts_open" title="Há conclusões para revisar" description="Escolha qual vale ou separe as regras por condição." tone="warning"><template #actions><MButton variant="secondary" @click="$emit('navigate', 'review')">Revisar conflitos</MButton></template></MAlert><MEmptyState v-else compact title="Tudo em ordem por aqui" description="Nenhum conflito aguardando sua decisão." icon="shield-check" /><div class="divider"></div><div class="row between"><div><h3>{{ n(overview.totals.memories) }} memórias no arquivo</h3><p class="muted">Conteúdo das conversas, organizado por assunto.</p></div><MButton icon="arrow-right" variant="ghost" accessibility-label="Abrir arquivo" @click="$emit('navigate', 'archive')" /></div><MButton variant="secondary" @click="$emit('navigate', 'evaluation')">Ver economia e qualidade</MButton></MCard>
    </div>
    <template v-else>
      <MCard gap="lg"><div class="section-heading"><div><h2>Comparações com tarefas reais</h2><p>Consumo total por execução. Qualidade verificada por testes.</p></div><MBadge text="Medição do provedor" tone="accent" /></div><MEmptyState v-if="!stats.comparisons.length" compact title="Ainda sem comparações" description="Os resultados aparecem aqui depois de executar a avaliação com tarefas reais." icon="chart-no-axes-combined" /><div v-for="item in stats.comparisons" :key="`${item.task}:${item.model}`" class="comparison"><div class="row between wrap"><div><h3>{{ item.task }}</h3><small>{{ item.model }} · {{ item.baseline.runs }} execuções sem memória / {{ item.memory.runs }} com memória</small></div><MBadge :text="item.quality_preserved ? 'Qualidade preservada' : 'Revisar qualidade'" :tone="item.quality_preserved ? 'success' : 'warning'" /></div><div class="comparison-bars"><div><span>Sem memória</span><div class="bar-track"><div class="bar baseline" :style="{ width: `${Math.max(1, item.baseline.tokens / Math.max(1, item.baseline.tokens, item.memory.tokens) * 100)}%` }"></div></div><b>{{ n(Math.round(item.baseline.tokens)) }}</b></div><div><span>Com memória</span><div class="bar-track"><div class="bar" :style="{ width: `${Math.max(1, item.memory.tokens / Math.max(1, item.baseline.tokens, item.memory.tokens) * 100)}%` }"></div></div><b>{{ n(Math.round(item.memory.tokens)) }}</b></div></div><p :class="item.token_change_percent !== null && item.token_change_percent < 0 ? 'positive' : 'muted'">{{ item.token_change_percent === null ? 'Comparação insuficiente' : `${item.token_change_percent > 0 ? '+' : ''}${item.token_change_percent.toFixed(1)}% de tokens` }} · {{ item.baseline.failures + item.memory.failures }} erros de ferramenta</p></div></MCard>
      <div class="two-columns"><MCard gap="md"><h2>Leituras que não se repetem</h2><dl class="facts"><div><dt>Conteúdo completo</dt><dd>{{ n(stats.reads.full) }}</dd></div><div><dt>Somente alterações</dt><dd>{{ n(stats.reads.delta) }}</dd></div><div><dt>Arquivo sem mudanças</dt><dd>{{ n(stats.reads.unchanged) }}</dd></div><div><dt>Tokens estimados emitidos</dt><dd>{{ n(stats.reads.emitted_tokens) }}</dd></div></dl></MCard><MCard gap="md"><h2>Por que um contexto ficou de fora</h2><dl class="facts"><div v-for="(label, key) in reasons" :key="key"><dt>{{ label }}</dt><dd>{{ n(stats.selection[key] || 0) }}</dd></div></dl><p class="muted">O feedback ajusta a utilidade. Ele não transforma uma observação em uma verdade confirmada.</p></MCard></div>
      <p class="muted fine-print">Repetições evitadas são uma estimativa local. A economia real depende da tarefa e só é demonstrada nas comparações acima; uma execução também pode gastar mais tokens.</p>
    </template>
  </div>
</template>
